bill-of-materials.pseudocode:
# bom: 품목 → [(자품목, 단위 소요량)]
def explode(item, qty, bom, need):
    need[item] = need.get(item, 0) + qty  # 총소요량 누적
    for child, per in bom.get(item, []):
        explode(child, qty * per, bom, need)  # 하위 전개
    return need

bom = {'자전거': [('프레임', 1), ('바퀴', 2)],
       '바퀴': [('림', 1), ('스포크', 36)]}
explode('자전거', 10, bom, {})
# → 자전거 10, 프레임 10, 바퀴 20, 림 20, 스포크 720

binary-insertion-sort.pseudocode:
def binary_insertion_sort(a):
    for i in range(1, len(a)):
        key = a[i]
        lo, hi = 0, i  # 정렬된 a[0..i-1]에서 탐색
        while lo < hi:  # 이진 탐색: 비교 O(log i)
            mid = (lo + hi) // 2
            if a[mid] <= key:  # 같으면 오른쪽 → 안정성
                lo = mid + 1
            else:
                hi = mid
        for j in range(i, lo, -1):  # 이동은 여전히 O(i)
            a[j] = a[j - 1]
        a[lo] = key
    return a

binary-search.pseudocode:
def binary_search(a, target):  # a는 오름차순 정렬
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2  # 오버플로 방지
        if a[mid] == target:
            return mid
        if a[mid] < target:
            lo = mid + 1  # 오른쪽 절반
        else:
            hi = mid - 1  # 왼쪽 절반
    return -1  # 없음, T(n)=T(n/2)+O(1) → O(log n)

binary-search-tree.pseudocode:
def search(node, key):
    while node is not None:
        if key == node.key:
            return node
        # 작으면 왼쪽, 크면 오른쪽 서브트리로
        node = node.left if key < node.key else node.right
    return None  # 탐색 실패

def insert(node, key):
    if node is None:
        return Node(key)  # 빈 자리에 새 노드
    if key < node.key:
        node.left = insert(node.left, key)
    elif key > node.key:
        node.right = insert(node.right, key)
    return node  # 중복 키는 삽입하지 않음

binary-semaphore.pseudocode:
class BinarySemaphore:
    def __init__(self, value=1):  # 1: 상호배제, 0: 신호용
        self.value = value
        self.queue = []  # 대기 스레드 목록

    def P(self):  # wait: 원자적으로 수행
        if self.value == 1:
            self.value = 0
        else:
            self.queue.append(current_thread())
            block()  # 대기 상태로 전환

    def V(self):  # signal: 원자적으로 수행
        if self.queue:
            wakeup(self.queue.pop(0))  # 값은 0 유지, 진입권 이양
        else:
            self.value = 1

bit-sliced-signature-file.pseudocode:
def bssf_query(slices, query_sig, n_docs):
    # slices[j]: 비트 위치 j의 문서별 비트(정수 비트맵)
    candidates = (1 << n_docs) - 1  # 모든 문서 후보
    for j, bit in enumerate(query_sig):
        if bit == 1:  # 질의 1비트 슬라이스만 읽음
            candidates &= slices[j]
    # 후보 비트맵 → 문서 번호 (false drop 검사 필요)
    return [d for d in range(n_docs)
            if candidates >> d & 1]
